use bevy::prelude::*;

use crate::field::{Field, FieldType};

// ── ForceField ─────────────────────────────────────────────────────────────────────────

/// Marks a force field generated by a Field tower.
#[derive(Component)]
#[require(Field, FieldType = FieldType::Force)]
pub struct ForceField;

/// Spawns a folded force field at `world_position`, generated by `tower_entity`.
#[derive(Component)]
pub struct BuilderForceField {
    pub tower_entity: Entity,
    pub world_position: Vec2,
}
impl BuilderForceField {
    pub fn new(tower_entity: Entity, world_position: Vec2) -> Self {
        Self { tower_entity, world_position }
    }
}

// ── CrucibleField ──────────────────────────────────────────────────────────────────────

/// Marks a crucible field generated by a Crucible tower.
#[derive(Component)]
#[require(Field, FieldType = FieldType::Crucible)]
pub struct CrucibleField;

/// Spawns a folded crucible field at `world_position`, generated by `tower_entity`.
#[derive(Component)]
pub struct BuilderCrucibleField {
    pub tower_entity: Entity,
    pub world_position: Vec2,
}
impl BuilderCrucibleField {
    pub fn new(tower_entity: Entity, world_position: Vec2) -> Self {
        Self { tower_entity, world_position }
    }
}
